using UnityEngine;
using UnityEditor;
using Codice.Characters;
using Codice.Mechanics;
using System;
public static class VerifyCombatReadability {
 public static string Run(){var a=new GameObject("Contact check");var p=new GameObject("Player check");var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.SetActive(false);int checks=0;Action<bool,string> check=(ok,msg)=>{if(!ok)throw new Exception(msg);checks++;};try{a.transform.position=new Vector3(3000,3000,3000);var pc=p.AddComponent<PlayerCharacter>();pc.State.Initialize(PlayerClass.Shinobi);Action<Vector3> pos=d=>{p.transform.position=a.transform.position+d;Physics.SyncTransforms();};pos(Vector3.forward*2);check(MeleeContact.CanHit(a.transform,pc,2.2f,.35f),"near contact");pos(Vector3.forward*4);check(!MeleeContact.CanHit(a.transform,pc,2.2f,.35f),"far rejection");pos(Vector3.back);check(!MeleeContact.CanHit(a.transform,pc,2.2f,.35f),"rear rejection");pos(Vector3.forward+Vector3.up*2);check(!MeleeContact.CanHit(a.transform,pc,2.2f,.35f),"height rejection");pos(Vector3.forward*2);wall.transform.position=a.transform.position+Vector3.forward+Vector3.up;wall.transform.localScale=new Vector3(3,3,.1f);wall.SetActive(true);Physics.SyncTransforms();check(!MeleeContact.CanHit(a.transform,pc,2.2f,.35f),"wall rejection");var s=p.AddComponent<PlayerStamina>();foreach(PlayerClass c in Enum.GetValues(typeof(PlayerClass))){pc.State.Initialize(c);s.SetNetwork(0);for(int i=0;i<100;i++)check(s.TrySpend(PlayerStamina.Action.Dodge)&&s.TrySpendAmount(999)&&s.Value==s.Max,"stamina restriction");}check(ShinobiGuard.ParryWindow==.4f,"parry window");var shader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Resources/Presentation/AshenMembrane.shader");check(shader&&shader.isSupported,"shader supported");foreach(var msg in ShaderUtil.GetShaderMessages(shader))check(msg.severity.ToString()!="Error",msg.message);return checks+" checks passed; shader supported";}finally{UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(p);UnityEngine.Object.DestroyImmediate(wall);}}
}
